"""Independent verifier written directly from PROTOCOL.md.

It replays the discrete state machine, recomputes every reported vector from
EARLIER REPORTED certified values and checks the worker/controller certificates.
Pure Python (no numpy) on purpose.
"""
import math

TOL = lambda a, b: 1e-7 + 1e-7 * max(abs(a), abs(b))


class VerifyError(Exception):
    pass


def close(a, b, ctx):
    if a is None or b is None:
        if a is not b:
            raise VerifyError('%s: %r vs %r' % (ctx, a, b))
        return
    if abs(a - b) > TOL(a, b):
        raise VerifyError('%s: %r != %r (tol %g)' % (ctx, a, b, TOL(a, b)))


def exact(a, b, ctx):
    if a != b:
        raise VerifyError('%s: %r != %r (exact)' % (ctx, a, b))


def is_num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def check_keys(obj, names, ctx):
    if not isinstance(obj, dict) or set(obj) != set(names):
        raise VerifyError('%s: keys %r != %r' % (ctx, sorted(obj) if isinstance(obj, dict) else obj, sorted(names)))


def numlist(v, n, ctx, lo=-1e9, hi=1e9):
    if not isinstance(v, list) or len(v) != n:
        raise VerifyError('%s: expected %d numbers, got %r' % (ctx, n, v if not isinstance(v, list) else len(v)))
    for x in v:
        if not is_num(x) or not (lo <= x <= hi):
            raise VerifyError('%s: bad number %r' % (ctx, x))


class Case:
    def __init__(self, case, results):
        self.case = case
        self.results = results
        self.E = len(case['edges'])
        self.K = len(case['commodities'])
        self.owned = [list(w) for w in case['workers']]
        self.W = len(self.owned)
        self.quorum = case['quorum']
        self.max_lag = case['max_lag']
        a, b = case['relax']
        self.alpha = a / b
        self.c = [e[2] for e in case['edges']]
        self.d = [com['demand'] for com in case['commodities']]
        self.slots = [[None if p is None else tuple(p) for p in com['paths']] for com in case['commodities']]
        self.mode = case['mode']
        self.rho = case['rho']
        self.reset()
        self.g = 0
        self.seq = 0
        self.issued = {}
        self.delivered = set()
        self.checkpoints = {}

    # -------------------------------------------------------------- helpers
    def reset(self):
        self.r = 0
        self.z = [0.0] * self.E
        self.u = [0.0] * self.E
        self.A = [[0.0] * self.E for _ in range(self.W)]
        self.flow = [[0.0] * len(self.slots[k]) for k in range(self.K)]
        self.seen = [False] * self.W
        self.fresh = set()
        self.last_round = [None] * self.W
        self.last_seq = [None] * self.W

    def live(self):
        return [self.c[e] > 0 for e in range(self.E)]

    def X(self):
        live = self.live()
        out = [0.0] * self.E
        for e in range(self.E):
            if live[e]:
                out[e] = sum(self.A[w][e] for w in range(self.W)) / self.c[e]
        return out

    def S(self):
        return [sum(self.A[w][e] for w in range(self.W)) for e in range(self.E)]

    def bias(self, w):
        live = self.live()
        X = self.X()
        out = [0.0] * self.E
        for e in range(self.E):
            if live[e]:
                out[e] = self.A[w][e] / self.c[e] + (self.z[e] - X[e] - self.u[e]) / self.W
            else:
                if out[e] != 0.0:
                    raise VerifyError('bias not exactly zero on withdrawn edge')
        return out

    def available(self, k):
        live = self.live()
        return [p is not None and all(live[e] for e in p) for p in self.slots[k]]

    def snapshot(self):
        return {'c': list(self.c), 'd': list(self.d), 'slots': [list(g) for g in self.slots],
                'mode': self.mode, 'rho': self.rho, 'r': self.r, 'z': list(self.z), 'u': list(self.u),
                'A': [list(row) for row in self.A], 'flow': [list(row) for row in self.flow],
                'seen': list(self.seen), 'fresh': set(self.fresh),
                'last_round': list(self.last_round), 'last_seq': list(self.last_seq)}

    def restore(self, snap):
        self.c = list(snap['c'])
        self.d = list(snap['d'])
        self.slots = [list(g) for g in snap['slots']]
        self.mode = snap['mode']
        self.rho = snap['rho']
        self.r = snap['r']
        self.z = list(snap['z'])
        self.u = list(snap['u'])
        self.A = [list(row) for row in snap['A']]
        self.flow = [list(row) for row in snap['flow']]
        self.seen = list(snap['seen'])
        self.fresh = set(snap['fresh'])
        self.last_round = list(snap['last_round'])
        self.last_seq = list(snap['last_seq'])

    # ---------------------------------------------------------------- events
    def run(self):
        if len(self.results) != len(self.case['events']):
            raise VerifyError('result count mismatch')
        for index, (event, result) in enumerate(zip(self.case['events'], self.results)):
            try:
                getattr(self, 'ev_' + event['op'])(event, result)
            except VerifyError as exc:
                raise VerifyError('event %d (%s): %s' % (index, event['op'], exc))
        return True

    def ev_configure(self, event, result):
        check_keys(result, ['op', 'generation'], 'configure result')
        exact(result['op'], 'configure', 'configure op')
        for edge_id, cap in event['capacity']:
            self.c[edge_id] = cap
        for k, dem in event['demand']:
            self.d[k] = dem
        for k, t, path in event['paths']:
            self.slots[k][t] = None if path is None else tuple(path)
        self.mode = event['mode']
        self.g += 1
        self.reset()
        self.flow = [[0.0] * len(self.slots[k]) for k in range(self.K)]
        exact(result['generation'], self.g, 'configure generation')

    def ev_issue(self, event, result):
        check_keys(result, ['op', 'id', 'worker', 'generation', 'bias', 'rho', 'result'], 'issue result')
        exact(result['op'], 'issue', 'issue op')
        exact(result['id'], event['id'], 'issue id')
        exact(result['worker'], event['worker'], 'issue worker')
        exact(result['generation'], self.g, 'issue generation')
        exact(result['rho'], self.rho, 'issue rho')
        w = event['worker']
        expected_bias = self.bias(w)
        numlist(result['bias'], self.E, 'issue bias')
        for e in range(self.E):
            close(result['bias'][e], expected_bias[e], 'bias[%d]' % e)
            if not self.live()[e]:
                exact(result['bias'][e], 0.0, 'bias withdrawn edge %d' % e)
        self.seq += 1
        proposal = result['result']
        self.check_proposal(w, proposal)
        self.issued[event['id']] = {'worker': w, 'seq': self.seq, 'gen': self.g,
                                    'proposal': proposal, 'owned': list(self.owned[w])}

    def check_proposal(self, w, proposal):
        owned = self.owned[w]
        mode = self.mode
        rho = self.rho
        live = self.live()
        bias = None
        if not isinstance(proposal, dict):
            raise VerifyError('proposal not a dict')
        unroutable = []
        for k in owned:
            avail = self.available(k)
            if self.d[k] > 0 and not any(avail):
                unroutable.append(k)
        if mode == 'route' and unroutable:
            check_keys(proposal, ['status', 'unroutable'], 'infeasible proposal')
            exact(proposal['status'], 'infeasible', 'proposal status')
            exact(proposal['unroutable'], sorted(unroutable), 'unroutable ids')
            return
        check_keys(proposal, ['status', 'flow', 'edge_load', 'potential'], 'optimal proposal')
        exact(proposal['status'], 'optimal', 'proposal status')
        if mode == 'route' and unroutable:
            raise VerifyError('route proposal must be infeasible')
        # flow shape and exact zeros
        if not isinstance(proposal['flow'], list) or len(proposal['flow']) != len(owned):
            raise VerifyError('flow shape')
        for j, k in enumerate(owned):
            row = proposal['flow'][j]
            if not isinstance(row, list) or len(row) != len(self.slots[k]):
                raise VerifyError('flow[%d] shape' % j)
            for t, value in enumerate(row):
                if not is_num(value) or not (0.0 <= value <= 1e9):
                    raise VerifyError('flow[%d][%d] range %r' % (j, t, value))
                avail = self.available(k)
                if (not avail[t]) or self.d[k] == 0:
                    exact(value, 0.0, 'flow[%d][%d] must be exactly zero' % (j, t))
        numlist(proposal['edge_load'], self.E, 'edge_load', 0.0, 1e9)
        if not isinstance(proposal['potential'], list) or len(proposal['potential']) != len(owned):
            raise VerifyError('potential shape')
        for value in proposal['potential']:
            if not is_num(value) or not (-1e9 <= value <= 1e9):
                raise VerifyError('potential range %r' % value)
            if mode == 'admit' and value < 0.0:
                raise VerifyError('admit potential negative %r' % value)
        # rebuild the captured problem from the reported bias of the issue event
        # (bias is checked separately; use the reported one, as a grader would)
        bias = self.bias(w)
        amounts = {}
        for j, k in enumerate(owned):
            for t, value in enumerate(proposal['flow'][j]):
                amounts[(k, t)] = float(value)
        load = [0.0] * self.E
        for (k, t), value in amounts.items():
            path = self.slots[k][t]
            if path is None or value == 0.0:
                continue
            for e in path:
                load[e] += value
        for e in range(self.E):
            if not live[e]:
                load[e] = 0.0
            close(proposal['edge_load'][e], load[e], 'edge_load[%d]' % e)
            if not live[e]:
                exact(proposal['edge_load'][e], 0.0, 'edge_load withdrawn %d' % e)
        total = 0.0
        penalty = 0.0
        for e in range(self.E):
            if live[e]:
                util = load[e] / self.c[e]
                penalty += (util - bias[e]) ** 2
                total += 0.0
        R = sum(amounts.values())
        f = 0.5 * sum(v * v for v in amounts.values()) + 0.5 * rho * penalty - (R if mode == 'admit' else 0.0)
        # feasibility and derivatives
        residual = 0.0
        for j, k in enumerate(owned):
            avail = self.available(k)
            mass = sum(proposal['flow'][j][t] for t in range(len(self.slots[k])) if avail[t] and self.d[k] > 0)
            if self.d[k] > 0 and any(avail):
                if mode == 'route':
                    close(mass, float(self.d[k]), 'commodity %d demand' % k)
                else:
                    if mass > self.d[k] + TOL(mass, self.d[k]):
                        raise VerifyError('commodity %d exceeds demand' % k)
            lam = float(proposal['potential'][j])
            if self.d[k] == 0 or not any(avail):
                exact(lam, 0.0, 'potential of commodity %d must be exactly zero' % k)
            for t in range(len(self.slots[k])):
                if not (avail[t] and self.d[k] > 0):
                    continue
                path = self.slots[k][t]
                x = float(proposal['flow'][j][t])
                G = x - (1.0 if mode == 'admit' else 0.0)
                for e in path:
                    G += rho * (load[e] / self.c[e] - bias[e]) / self.c[e]
                if G + lam < -TOL(G, lam):
                    raise VerifyError('commodity %d slot %d: G+lambda = %g < 0' % (k, t, G + lam))
                residual += x * (G + lam)
        D = f - residual
        if abs(f - D) > TOL(f, D):
            raise VerifyError('certificate f=%r D=%r residual=%r' % (f, D, residual))

    def ev_deliver(self, event, result):
        check_keys(result, ['op', 'id', 'status'], 'deliver result')
        exact(result['op'], 'deliver', 'deliver op')
        exact(result['id'], event['id'], 'deliver id')
        ticket = event['id']
        if ticket in self.delivered:
            expected = 'duplicate'
        else:
            record = self.issued[ticket]
            if record['gen'] != self.g:
                expected = 'obsolete'
            elif self.last_seq[record['worker']] is not None and record['seq'] < self.last_seq[record['worker']]:
                expected = 'superseded'
            elif record['proposal'].get('status') != 'optimal':
                expected = 'infeasible'
            else:
                expected = 'accepted'
            self.delivered.add(ticket)
        exact(result['status'], expected, 'deliver status')
        if expected == 'accepted':
            record = self.issued[ticket]
            w = record['worker']
            proposal = record['proposal']
            for j, k in enumerate(record['owned']):
                self.flow[k] = [float(v) for v in proposal['flow'][j]]
            self.A[w] = [float(v) for v in proposal['edge_load']]
            self.seen[w] = True
            self.fresh.add(w)
            self.last_round[w] = self.r
            self.last_seq[w] = record['seq']

    def ages(self):
        return [None if not self.seen[w] else self.r - self.last_round[w] for w in range(self.W)]

    def ev_step(self, event, result):
        ages = self.ages()
        missing = [w for w in range(self.W) if not self.seen[w]]
        stale = [w for w in range(self.W) if ages[w] is not None and ages[w] > self.max_lag]
        fresh = sorted(self.fresh)
        can = (not missing) and (not stale) and len(fresh) >= self.quorum
        exact(result['op'], 'step', 'step op')
        if not can:
            check_keys(result, ['op', 'status', 'missing', 'stale', 'fresh'], 'waiting step')
            exact(result['status'], 'waiting', 'step status')
            exact(result['missing'], missing, 'missing')
            exact(result['stale'], stale, 'stale')
            exact(result['fresh'], fresh, 'fresh')
            return
        check_keys(result, ['op', 'status', 'round', 'load', 'ceiling', 'z', 'dual', 'pressure'], 'advanced step')
        exact(result['status'], 'advanced', 'step status')
        live = self.live()
        S = self.S()
        X = self.X()
        z0 = list(self.z)
        u0 = list(self.u)
        rho = float(self.rho)
        numlist(result['load'], self.E, 'step load', 0.0, 1e9)
        numlist(result['z'], self.E, 'step z')
        numlist(result['dual'], self.E, 'step dual')
        numlist(result['pressure'], self.E, 'step pressure', 0.0, 1e9)
        for e in range(self.E):
            close(result['load'][e], S[e], 'load[%d]' % e)
            if not live[e]:
                exact(result['z'][e], 0.0, 'z withdrawn %d' % e)
                exact(result['dual'][e], 0.0, 'dual withdrawn %d' % e)
                exact(result['pressure'][e], 0.0, 'pressure withdrawn %d' % e)
        if not is_num(result['ceiling']) or not (0.0 <= result['ceiling'] <= 1e9):
            raise VerifyError('ceiling range')
        h = float(result['ceiling'])
        if not any(live):
            exact(h, 0.0 if self.mode == 'route' else 1.0, 'ceiling with no live edges')
        V = [0.0] * self.E
        for e in range(self.E):
            if live[e]:
                V[e] = self.alpha * X[e] + (1.0 - self.alpha) * z0[e] + u0[e]
        zsum = 0.0
        for e in range(self.E):
            if not live[e]:
                continue
            close(rho * (result['z'][e] - V[e]) + result['pressure'][e], 0.0, 'pressure identity %d' % e)
            close(result['pressure'][e] * (h - result['z'][e]), 0.0, 'complementarity %d' % e)
            if result['pressure'][e] < -TOL(0.0, result['pressure'][e]):
                raise VerifyError('negative pressure %d' % e)
            if result['z'][e] > h + TOL(result['z'][e], h):
                raise VerifyError('z above ceiling %d' % e)
            close(result['dual'][e], u0[e] + self.alpha * X[e] + (1.0 - self.alpha) * z0[e] - result['z'][e],
                  'dual identity %d' % e)
            zsum += result['pressure'][e]
        if self.mode == 'route':
            if 1.0 - zsum < -TOL(1.0, zsum):
                raise VerifyError('route pressure sum %g > 1' % zsum)
            close(h * (1.0 - zsum), 0.0, 'route ceiling complementarity')
        if h < 0.0:
            raise VerifyError('negative ceiling')
        exact(result['round'], self.r + 1, 'new round')
        self.z = [float(v) for v in result['z']]
        self.u = [float(v) for v in result['dual']]
        self.r += 1
        self.fresh = set()

    def ev_retune(self, event, result):
        check_keys(result, ['op', 'rho'], 'retune result')
        exact(result['op'], 'retune', 'retune op')
        exact(result['rho'], event['rho'], 'retune rho')
        old = self.rho
        scale = old / event['rho']
        for e in range(self.E):
            close(self.u[e] * scale, self.u[e] * scale, 'noop')
        self.u = [v * scale for v in self.u]
        self.rho = event['rho']

    def ev_save(self, event, result):
        check_keys(result, ['op', 'name'], 'save result')
        exact(result['op'], 'save', 'save op')
        exact(result['name'], event['name'], 'save name')
        self.checkpoints[event['name']] = self.snapshot()

    def ev_restore(self, event, result):
        check_keys(result, ['op', 'name', 'generation'], 'restore result')
        exact(result['op'], 'restore', 'restore op')
        exact(result['name'], event['name'], 'restore name')
        self.restore(self.checkpoints[event['name']])
        self.g += 1
        exact(result['generation'], self.g, 'restore generation')

    def ev_audit(self, event, result):
        check_keys(result, ['op', 'generation', 'round', 'rho', 'flow', 'worker_load', 'load', 'z',
                            'dual', 'seen', 'fresh', 'age'], 'audit result')
        exact(result['op'], 'audit', 'audit op')
        exact(result['generation'], self.g, 'audit generation')
        exact(result['round'], self.r, 'audit round')
        exact(result['rho'], self.rho, 'audit rho')
        if not isinstance(result['flow'], list) or len(result['flow']) != self.K:
            raise VerifyError('audit flow shape')
        for k in range(self.K):
            row = result['flow'][k]
            if not isinstance(row, list) or len(row) != len(self.slots[k]):
                raise VerifyError('audit flow[%d] shape' % k)
            for t, value in enumerate(row):
                if not is_num(value) or not (0.0 <= value <= 1e9):
                    raise VerifyError('audit flow range')
                close(value, self.flow[k][t], 'audit flow[%d][%d]' % (k, t))
        if not isinstance(result['worker_load'], list) or len(result['worker_load']) != self.W:
            raise VerifyError('audit worker_load shape')
        for w in range(self.W):
            numlist(result['worker_load'][w], self.E, 'audit worker_load[%d]' % w, 0.0, 1e9)
            for e in range(self.E):
                close(result['worker_load'][w][e], self.A[w][e], 'audit worker_load[%d][%d]' % (w, e))
        numlist(result['load'], self.E, 'audit load', 0.0, 1e9)
        numlist(result['z'], self.E, 'audit z')
        numlist(result['dual'], self.E, 'audit dual')
        for e in range(self.E):
            close(result['load'][e], self.S()[e], 'audit load[%d]' % e)
            close(result['z'][e], self.z[e], 'audit z[%d]' % e)
            close(result['dual'][e], self.u[e], 'audit dual[%d]' % e)
        exact(result['seen'], [w for w in range(self.W) if self.seen[w]], 'audit seen')
        exact(result['fresh'], sorted(self.fresh), 'audit fresh')
        exact(result['age'], self.ages(), 'audit age')


def verify(request, response):
    if not isinstance(response, dict):
        raise VerifyError('response not an object')
    check_keys(response, ['cases'], 'response')
    cases = response['cases']
    if not isinstance(cases, list) or len(cases) != len(request['cases']):
        raise VerifyError('case count mismatch')
    for case, results in zip(request['cases'], cases):
        check_keys(results, ['events'], 'case result')
        Case(case, results['events']).run()
    return True
